macro_rules! deps {
    () => {
        SelectHandle!();
        RecvError!();
    };
}

macro_rules! Select {
    () => {
        deps!();
        # [doc = " Selects from a set of channel operations."] # [doc = ""] # [doc = " `Select` allows you to define a set of channel operations, wait until any one of them becomes"] # [doc = " ready, and finally execute it. If multiple operations are ready at the same time, a random one"] # [doc = " among them is selected."] # [doc = ""] # [doc = " An operation is considered to be ready if it doesn't have to block. Note that it is ready even"] # [doc = " when it will simply return an error because the channel is disconnected."] # [doc = ""] # [doc = " The [`select!`] macro is a convenience wrapper around `Select`. However, it cannot select over a"] # [doc = " dynamically created list of channel operations."] # [doc = ""] # [doc = " [`select!`]: crate::select!"] # [doc = ""] # [doc = " Once a list of operations has been built with `Select`, there are two different ways of"] # [doc = " proceeding:"] # [doc = ""] # [doc = " * Select an operation with [`try_select`], [`select`], or [`select_timeout`]. If successful,"] # [doc = "   the returned selected operation has already begun and **must** be completed. If we don't"] # [doc = "   complete it, a panic will occur."] # [doc = ""] # [doc = " * Wait for an operation to become ready with [`try_ready`], [`ready`], or [`ready_timeout`]. If"] # [doc = "   successful, we may attempt to execute the operation, but are not obliged to. In fact, it's"] # [doc = "   possible for another thread to make the operation not ready just before we try executing it,"] # [doc = "   so it's wise to use a retry loop. However, note that these methods might return with success"] # [doc = "   spuriously, so it's a good idea to always double check if the operation is really ready."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " Use [`select`] to receive a message from a list of receivers:"] # [doc = ""] # [doc = " ```"] # [doc = " use crossbeam_channel::{Receiver, RecvError, Select};"] # [doc = ""] # [doc = " fn recv_multiple<T>(rs: &[Receiver<T>]) -> Result<T, RecvError> {"] # [doc = "     // Build a list of operations."] # [doc = "     let mut sel = Select::new();"] # [doc = "     for r in rs {"] # [doc = "         sel.recv(r);"] # [doc = "     }"] # [doc = ""] # [doc = "     // Complete the selected operation."] # [doc = "     let oper = sel.select();"] # [doc = "     let index = oper.index();"] # [doc = "     oper.recv(&rs[index])"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " Use [`ready`] to receive a message from a list of receivers:"] # [doc = ""] # [doc = " ```"] # [doc = " use crossbeam_channel::{Receiver, RecvError, Select};"] # [doc = ""] # [doc = " fn recv_multiple<T>(rs: &[Receiver<T>]) -> Result<T, RecvError> {"] # [doc = "     // Build a list of operations."] # [doc = "     let mut sel = Select::new();"] # [doc = "     for r in rs {"] # [doc = "         sel.recv(r);"] # [doc = "     }"] # [doc = ""] # [doc = "     loop {"] # [doc = "         // Wait until a receive operation becomes ready and try executing it."] # [doc = "         let index = sel.ready();"] # [doc = "         let res = rs[index].try_recv();"] # [doc = ""] # [doc = "         // If the operation turns out not to be ready, retry."] # [doc = "         if let Err(e) = res {"] # [doc = "             if e.is_empty() {"] # [doc = "                 continue;"] # [doc = "             }"] # [doc = "         }"] # [doc = ""] # [doc = "         // Success!"] # [doc = "         return res.map_err(|_| RecvError);"] # [doc = "     }"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " [`try_select`]: Select::try_select"] # [doc = " [`select`]: Select::select"] # [doc = " [`select_timeout`]: Select::select_timeout"] # [doc = " [`try_ready`]: Select::try_ready"] # [doc = " [`ready`]: Select::ready"] # [doc = " [`ready_timeout`]: Select::ready_timeout"] pub struct Select < 'a > { # [doc = " A list of senders and receivers participating in selection."] handles : Vec < (& 'a dyn SelectHandle , usize , * const u8) > , # [doc = " The next index to assign to an operation."] next_index : usize , # [doc = " Whether to use the index of handles as bias for selecting ready operations."] biased : bool , }
    };
}

Select!()